CREATE    VIEW [D365_Exception].[vwDuplicatePayments] AS

WITH 
CANC AS (
SELECT
 VOUCHER
,TXT
FROM [synapse_fo].[CUSTTRANS_RICS]
WHERE TXT LIKE 'Cancelled: %'
),

TT AS (
SELECT
 ACCOUNTNUM
,AMOUNTCUR
,ORDERNUM
,TRANSDATE
,COUNT(TOK.CUSTTRANSRECID) AS DupCount
,SUM(CASE WHEN CANC.TXT IS NULL THEN 0 else 1 END) AS CancelCount
FROM [synapse_fo].[CUSTTRANS_RICS] TOK
LEFT JOIN CANC AS CANC ON CANC.VOUCHER = TOK.LASTSETTLEVOUCHER
WHERE TRANSTYPE = 15
GROUP BY ACCOUNTNUM, ORDERNUM, TRANSDATE, AMOUNTCUR
HAVING COUNT(TOK.CUSTTRANSRECID) > 1
)

SELECT TT.DupCount, CancelCount, CASE WHEN DupCount - CancelCount = 1 THEN 'Resolved' ELSE 'Outstanding' END AS 'Dupe Status', TIK.*,
ROW_NUMBER() OVER(ORDER BY TIK.RECID) AS CUSTTRANSID
FROM [synapse_fo].[CUSTTRANS_RICS] TIK
INNER JOIN TT TT 
	ON TT.ACCOUNTNUM = TIK.ACCOUNTNUM
	AND TT.ORDERNUM = TIK.ORDERNUM
	AND TT.AMOUNTCUR = TIK.AMOUNTCUR
